def load() -> pd.DataFrame:
    import openpyxl
    wb = openpyxl.load_workbook('data/archeology/input/climateMeasurements.xlsx', read_only=True)
    ws = wb['Sheet1']
    rows = []
    for i, row in enumerate(ws.iter_rows(values_only=True)):
        # Look for rows that contain string values that might be headers
        str_vals = [v for v in row if isinstance(v, str) and len(v) > 1]
        if len(str_vals) > 3:
            rows.append({'row_idx': i, 'values': str(row[:20])})
        if i > 200:
            break
    wb.close()
    return pd.DataFrame(rows)

