def process(load_data):
    df = load_data[['Ca', 'ODP 967 Dust proxy', 'ODP 967 wet-dry index']].dropna(subset=['ODP 967 Dust proxy'])
    min_dust = df['ODP 967 Dust proxy'].min()
    ties = df[df['ODP 967 Dust proxy'] == min_dust]
    result = ties.sort_values('ODP 967 wet-dry index').iloc[0]
    return pd.DataFrame({'Ca': [result['Ca']], 'ODP 967 Dust proxy': [result['ODP 967 Dust proxy']], 'ODP 967 wet-dry index': [result['ODP 967 wet-dry index']], 'Ca_rounded': [round(result['Ca'], 4)]})
